#!/usr/bin/env python3
"""Feed a JSON object with a single key (given as raw JSON-source bytes for the key string)
and report the rendered LHS path."""
import subprocess, sys, json

EXE = "/workspace/executable"

def run(data, args=()):
    p = subprocess.run([EXE, *args], input=data, capture_output=True)
    return p.stdout, p.stderr, p.returncode

def path_for_keysrc(keysrc_bytes):
    """keysrc_bytes: the bytes that go inside the JSON string literal quotes."""
    data = b'{"' + keysrc_bytes + b'":1}'
    out, err, rc = run(data)
    lines = out.split(b"\n")
    # find the line that is not 'json = {};'
    for ln in lines:
        if ln.startswith(b"json") and not ln == b"json = {};" and ln:
            return ln, err, rc
    return None, err, rc

def esc(b):
    return b.decode("utf-8", "backslashreplace")

