import json, unicodedata
from collections import defaultdict
d = json.load(open('verdicts.json'))
rf = {int(k):v for k,v in d['first'].items()}
rc = {int(k):v for k,v in d['cont'].items()}
F={'Lu','Ll','Lt','Lm','Lo','Nl'}; C=F|{'Nd','Mn','Mc','Pc'}
def cat(c): return unicodedata.category(chr(c))
mf=[c for c in rf if rf[c] != (c in (0x24,0x5f) or cat(c) in F)]
mc=[c for c in rc if rc[c] != (c in (0x24,0x5f) or cat(c) in C)]
print('unidata',unicodedata.unidata_version)
print('FIRST mismatches:',len(mf))
g=defaultdict(list)
for c in mf: g[(cat(c),rf[c])].append(c)
for k,v in sorted(g.items()): print('  ',k,len(v),['U+%04X'%x for x in v[:12]])
print('CONT mismatches:',len(mc))
g=defaultdict(list)
for c in mc: g[(cat(c),rc[c])].append(c)
for k,v in sorted(g.items()): print('  ',k,len(v),['U+%04X'%x for x in v[:12]])
print()
print('Sc bare:',['U+%04X'%c for c in rf if cat(c)=='Sc' and rf[c]])
print('Pc bare first:',['U+%04X'%c for c in rf if cat(c)=='Pc' and rf[c]])
print('Pc quoted cont:',['U+%04X'%c for c in rc if cat(c)=='Pc' and not rc[c]])
print('Lt count:',sum(1 for c in rf if cat(c)=='Lt'),'bare first:',sum(1 for c in rf if cat(c)=='Lt' and rf[c]),'bare cont:',sum(1 for c in rc if cat(c)=='Lt' and rc[c]))
print('bare-first but not bare-cont:',['U+%04X'%c for c in rf if rf[c] and not rc[c]])
"

